styleBlocks.css:
.dashboard-biometric-picker .dashboard-widget-picker-section {
  min-height: 0;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
}

.dashboard-biometric-picker .dashboard-biometric-widget-grid {
  min-height: 0;
  flex: 1 1 auto;
  max-height: none;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.dashboard-widget-picker-label {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 800;
  color: var(--text-muted);
  text-transform: uppercase;
}

.dashboard-widget-picker-search {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
}

.dashboard-widget-picker-card {
  display: flex; flex-direction: column; align-items: flex-start; gap: 4px;
  width: 100%; padding: 14px; border-radius: var(--radius);
  background: var(--bg-card); border: 1px solid var(--border);
  color: var(--text-primary); font: inherit; text-align: left; cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}

.dashboard-widget-picker-empty {
  padding: 14px; border: 1px dashed var(--border); border-radius: var(--radius);
  color: var(--text-muted); font-size: 13px;
}

.import-map-context {
  display: grid;
  gap: 4px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border);
}

.import-map-modal-search {
  width: 100%;
  min-height: 38px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
}

.import-map-modal-grid {
  display: grid;
  grid-template-columns: minmax(160px, 220px) minmax(0, 1fr);
  gap: 12px;
  min-height: 420px;
}

.import-map-categories,
.import-map-results {
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.import-map-category {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  padding: 9px 10px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  text-align: left;
}

.import-map-category.active,
.import-map-category:hover,
.import-map-category:focus {
  background: var(--bg-hover);
  color: var(--text-primary);
  outline: none;
}

.import-map-result {
  display: grid;
  gap: 6px;
  width: 100%;
  padding: 10px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-primary);
  cursor: pointer;
  text-align: left;
  font: inherit;
}

.import-map-result:hover,
.import-map-result:focus,
.import-map-result.selected {
  background: color-mix(in srgb, var(--accent) 14%, var(--bg-card));
  outline: none;
}

.import-map-result-main {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}

.import-map-result-main code {
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 11px;
}

.import-map-result-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  color: var(--text-muted);
  font-size: 11px;
}

.import-map-result-meta span {
  padding: 2px 6px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
}

.import-map-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 16px 16px;
  border-top: 1px solid var(--border);
}
